reference_solution:
def camelcase_matches(queries, pattern):
 answer=[]
 for query in queries:
  at=0
  for char in query:
   if at<len(pattern) and char==pattern[at]:at+=1
   elif char.isupper():break
  else:answer.append(at==len(pattern));continue
  answer.append(False)
 return answer

